/**
 * The Worker side of the bridge to the desktop's server code (registry
 * generated by scripts/gen-web-bridge.ts). Actions are called by key and
 * name; a route handler gets a real Request and its Response streams back:
 * first the head, then every body chunk as it is produced, so an event
 * stream (triage, compose, import…) reaches the page live.
 */
import { ACTIONS, ROUTES } from './registry.gen'

export async function action(key: string, name: string, args: unknown[]): Promise<unknown> {
  const fn = ACTIONS[key]?.[name]
  if (!fn) {
    throw Object.assign(new Error(`No action ${key}#${name} in the browser edition.`), {
      code: 'not-in-browser',
    })
  }
  return fn(...args)
}

export type RouteEvent =
  | { kind: 'head'; status: number; headers: [string, string][] }
  | { kind: 'chunk'; bytes: Uint8Array }

export type RouteRequest = {
  method: string
  headers: [string, string][]
  body: string | Uint8Array | null
}

export async function route(
  path: string,
  req: RouteRequest,
  onEvent: (event: RouteEvent) => void,
): Promise<void> {
  const url = new URL(path, 'https://cvforge.invalid')
  const handler = ROUTES[url.pathname.replace(/\/$/, '')]?.[req.method]
  if (!handler) {
    onEvent({ kind: 'head', status: 404, headers: [['content-type', 'text/plain']] })
    onEvent({ kind: 'chunk', bytes: new TextEncoder().encode('Not in the browser edition.') })
    return
  }
  const request = new Request(url, {
    method: req.method,
    headers: req.headers,
    body: req.method === 'GET' || req.method === 'HEAD' ? null : (req.body as BodyInit | null),
  })
  const response = (await handler(request, { params: Promise.resolve({}) })) as Response
  onEvent({ kind: 'head', status: response.status, headers: [...response.headers.entries()] })
  if (!response.body) return
  const reader = response.body.getReader()
  for (;;) {
    const { done, value } = await reader.read()
    if (done) return
    onEvent({ kind: 'chunk', bytes: value })
  }
}
